package com.match.transfer;import com.fasterxml.jackson.databind.ObjectMapper;import com.match.agent.model.*;import com.match.agent.persistence.*;import com.match.agent.service.AgentCommandService;import com.match.environment.persistence.*;import com.match.resource.service.ResourceStorageService;import org.springframework.context.event.EventListener;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.multipart.MultipartFile;import java.time.LocalDateTime;import java.util.*;
@Service public class TemporaryTransferService{private final TemporaryTransferMapper mapper;private final TrainingEnvironmentMapper environments;private final ProcessingAgentMapper agents;private final ResourceStorageService storage;private final AgentCommandService commands;private final ObjectMapper json;public TemporaryTransferService(TemporaryTransferMapper m,TrainingEnvironmentMapper e,ProcessingAgentMapper a,ResourceStorageService s,AgentCommandService c,ObjectMapper j){mapper=m;environments=e;agents=a;storage=s;commands=c;json=j;}@Transactional public TemporaryTransferRecord upload(int userId,boolean admin,String environmentId,MultipartFile file){TrainingEnvironmentRecord env=environments.selectForUpdate(environmentId);if(env==null||(!admin&&!Integer.valueOf(userId).equals(env.getUserId())))throw new IllegalArgumentException("无权操作该实训环境");String name=file==null?null:org.apache.commons.io.FilenameUtils.getName(file.getOriginalFilename());if(name==null||name.trim().isEmpty()||".".equals(name)||"..".equals(name))throw new IllegalArgumentException("文件名无效");ResourceStorageService.StoredFile stored=storage.store(file);TemporaryTransferRecord r=new TemporaryTransferRecord();r.setTransferId(UUID.randomUUID().toString());r.setUserId(env.getUserId());r.setEnvironmentId(environmentId);r.setFileName(name);r.setStorageKey(stored.getStorageKey());r.setSha256(stored.getSha256());r.setState("PENDING");r.setExpiresAt(LocalDateTime.now().plusHours(24));r.setCreatedAt(LocalDateTime.now());r.setUpdatedAt(r.getCreatedAt());try{mapper.insert(r);Map<String,Object>p=new LinkedHashMap<>();p.put("downloadPath","/agent/v1/files/"+stored.getStorageKey());p.put("targetRelativePath",env.getWorkspaceRelativePath()+"/datasets/"+name);p.put("sha256",stored.getSha256());ProcessingAgentRecord agent=agents.selectForManagement(env.getAgentId());AgentCommandView cmd=commands.requestEnvironmentCommand(agent,"TRANSFER_FILE",json.writeValueAsString(p),userId,admin?"ADMIN":"USER",environmentId+":TRANSFER:"+r.getTransferId());r.setCommandId(cmd.getCommandId());r.setState("DISPATCHED");mapper.updateById(r);return r;}catch(Exception x){try{storage.delete(stored.getStorageKey());}catch(RuntimeException cleanup){x.addSuppressed(cleanup);}throw new IllegalStateException("数据集传输任务提交失败",x);}}public List<TemporaryTransferRecord> list(int userId){return mapper.selectByUser(userId);}@EventListener @Transactional public void done(AgentCommandFinishedEvent e){if(!"TRANSFER_FILE".equals(e.getCommandType()))return;TemporaryTransferRecord r=mapper.selectByCommand(e.getCommandId());if(r==null)return;r.setState(e.isSuccess()?"SUCCEEDED":"FAILED");r.setUpdatedAt(LocalDateTime.now());mapper.updateById(r);if(e.isSuccess())storage.delete(r.getStorageKey());}@Scheduled(fixedDelay=3600000)public void cleanup(){for(TemporaryTransferRecord r:mapper.selectExpired(LocalDateTime.now())){storage.delete(r.getStorageKey());mapper.deleteById(r.getTransferId());}}}
